const SL={COMPLETED:'Completed',UNKNOWN:'Unknown',RECRUITING:'Recruiting',TERMINATED:'Terminated',ACTIVE_NOT_RECRUITING:'Active, not recruiting',WITHDRAWN:'Withdrawn',NOT_YET_RECRUITING:'Not yet recruiting',ENROLLING_BY_INVITATION:'Enrolling by invitation',SUSPENDED:'Suspended'};
